-- Queer Atlas: Stuttgart city package
-- Researched 2026-10-27 from first-party municipal, community, venue and organiser sources.
-- Idempotent: matching city/name rows are updated; missing rows are inserted.
--
-- Core research:
-- https://www.stuttgart.de/en/buergerinnen-und-buerger/chancengleichheit/lsbttiq/
-- https://www.zentrum-weissenburg.de/kontakt/
-- https://www.stuttgart-pride.de/alle-infos-zur-hocketse/
-- https://www.aidshilfe-stuttgart.de/

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.services add column if not exists service_intel jsonb not null default '{}'::jsonb;

do $qa_require_qari$
begin
  if not exists (
    select 1 from public.qa_qari_profiles
    where destination_key = 'country:germany' and scope_type = 'country' and is_published = true
  ) then
    raise exception 'Published QARI profile country:germany is required before Stuttgart can be published.';
  end if;
end;
$qa_require_qari$;

with src as (
  select * from jsonb_to_recordset($qa_cities$
[
  {
    "slug":"stuttgart","name":"Stuttgart","title":"Queer Stuttgart","country":"Germany","country_code":"DE","latitude":48.7758,"longitude":9.1829,"timezone":"Europe/Berlin",
    "vibe":"hilly, warm-hearted and community-connected",
    "local_mood":"Stuttgart's queer life is less a single party district than a linked network of community rooms, neighbourhood bars, sauna culture, touring club nights and unusually visible civic infrastructure.",
    "queer_status":"The city funds LGBTIQ+ coordination and counselling, while Weissenburg, Stuttgart PRIDE, AIDS-Hilfe and trans-led community work give visitors practical routes into local life. Permanent nightlife is compact; the calendar matters.",
    "crowd_profile":"Queer locals across ages, students, LGBTQIA+ families, gay and bi men, trans and non-binary communities, community organisers, techno regulars and visitors from Baden-Württemberg meet in different spaces rather than one uniform scene.",
    "introduction":"Stuttgart rewards people who read it as a network. Start in the South at Weissenburg or Reboots for low-pressure connection, use Viva for an adult sauna option, and follow named programmes such as Love*Pop at Lehmann rather than expecting every club night to be queer. The major annual peak is Stuttgart PRIDE: its demonstration, community information mile and Hocketse bring public visibility to the centre. Between those moments, the municipal directory and organiser calendars are more useful than stale nightlife lists.",
    "guide_items":[
      {"title":"About","text":"Stuttgart has a compact commercial scene but substantial civic and community infrastructure. Its strongest queer signal is a web of organisations, cafés, health routes and recurring events—not a giant gay village."},
      {"title":"Districts","text":"Stuttgart-Süd around Weißenburgstraße and Bopser is the clearest community base. The centre and Olgaeck connect Reboots, Viva and Pride activity; club nights may be elsewhere, so check the exact host and return route."},
      {"title":"Safety","text":"Germany's legal context and Stuttgart's municipal support are useful signals, not a guarantee of identical comfort in every street or venue. Keep usual late-night awareness, use current organiser information, and ask service providers directly about access needs."},
      {"title":"Nightlife","text":"Begin with Weissenburg or Reboots if you want a social entry point, then choose a named night such as Love*Pop at Lehmann. Doors, line-ups and locations change; do not rely on old listings or assume an inclusive mixed venue is queer every night."},
      {"title":"Cost","text":"Drinks are moderate for a major German city, but Stuttgart's trade fairs, football weekends and Pride can sharply raise hotel prices. A central transit-connected base reduces the friction of the city's hills and spread-out evening plans."}
    ],
    "guide_sources":[
      {"label":"City of Stuttgart: Queer life","url":"https://www.stuttgart.de/en/buergerinnen-und-buerger/chancengleichheit/lsbttiq/"},
      {"label":"Weissenburg e.V.","url":"https://www.zentrum-weissenburg.de/kontakt/"},
      {"label":"Stuttgart PRIDE","url":"https://www.stuttgart-pride.de/"},
      {"label":"AIDS-Hilfe Stuttgart","url":"https://www.aidshilfe-stuttgart.de/"}
    ],
    "safety_context":"Stuttgart has municipal LGBTIQ+ coordination and established support organisations, but programme and venue conditions still vary. Confirm same-day event details, protect belongings on crowded transit, and use direct provider contact for access, privacy or urgent support needs.",
    "qari_key":"country:germany"
  }
]
$qa_cities$) c(slug text,name text,title text,country text,country_code text,latitude double precision,longitude double precision,timezone text,vibe text,local_mood text,queer_status text,crowd_profile text,introduction text,guide_items jsonb,guide_sources jsonb,safety_context text,qari_key text)
)
insert into public.qa_cities(slug,name,title,country,country_code,latitude,longitude,map_confirmed,timezone,vibe,local_mood,queer_status,crowd_profile,introduction,guide_items,guide_sources,guide_checked_at,safety_context,qari_destination_key,qari_score,qari_summary,qari_confidence,status,updated_at)
select c.slug,c.name,c.title,c.country,c.country_code,c.latitude,c.longitude,true,c.timezone,c.vibe,c.local_mood,c.queer_status,c.crowd_profile,c.introduction,c.guide_items,c.guide_sources,date '2026-10-27',c.safety_context,q.destination_key,q.qari_score,q.summary,q.confidence,'published',timezone('utc',now())
from src c cross join lateral (select destination_key,qari_score,summary,confidence from public.qa_qari_profiles where destination_key=c.qari_key and scope_type='country' and is_published=true order by reviewed_at desc nulls last limit 1) q
on conflict(slug) do update set name=excluded.name,title=excluded.title,country=excluded.country,country_code=excluded.country_code,latitude=excluded.latitude,longitude=excluded.longitude,map_confirmed=true,timezone=excluded.timezone,vibe=excluded.vibe,local_mood=excluded.local_mood,queer_status=excluded.queer_status,crowd_profile=excluded.crowd_profile,introduction=excluded.introduction,guide_items=excluded.guide_items,guide_sources=excluded.guide_sources,guide_checked_at=excluded.guide_checked_at,safety_context=excluded.safety_context,qari_destination_key=excluded.qari_destination_key,qari_score=excluded.qari_score,qari_summary=excluded.qari_summary,qari_confidence=excluded.qari_confidence,status='published',updated_at=excluded.updated_at;

with raw_places as (
  select * from jsonb_to_recordset($qa_places$
[
  {"name":"Weissenburg e.V. – Zentrum LSBTIQA+ Stuttgart","city":"stuttgart","type":"cafe","description":"Stuttgart's non-commercial queer centre is both a café and a practical front door into local groups, counselling and community events. It is especially valuable for a first evening when a conventional bar crawl is not the point: regulars, board games, group notices and volunteer hosts make it a low-pressure place to get oriented.","hours":"Café Tuesday-Friday 19:00-22:00 and Sunday 15:00-20:00; group and counselling access varies. Confirm current programme before visiting.","link":"https://www.zentrum-weissenburg.de/kontakt/","location":"Weißenburgstraße 28A, 70180 Stuttgart, Germany","lat":48.767623,"lng":9.178081,"vibe":"community-run queer living room, café and local-information hub","q":"Small café capacity; public events and group meetings can change the atmosphere.","best":"A weekday early evening or Sunday afternoon for an easy first contact.","crowd":"LGBTQIA+ locals across ages, community groups, first-time visitors and friends.","dress":"Everyday casual.","staff":"Dedicated LSBTIQA+ community centre with counselling and group infrastructure.","sources":["https://www.zentrum-weissenburg.de/kontakt/","https://www.stuttgart.de/en/buergerinnen-und-buerger/chancengleichheit/lsbttiq/queere-beratungsangebote"]},
  {"name":"Reboots","city":"stuttgart","type":"bar","description":"A warm, western-styled queer neighbourhood bar in Stuttgart-Süd where karaoke, bingo, TV nights and puzzles make conversation as important as drinking. It is a better first stop than a performance of nightlife: the scale is intimate, the crowd is mixed and the programme gives solo visitors a natural way in.","hours":"Tuesday-Thursday 19:00-00:00; Friday 19:00-03:00; Saturday 18:00-03:00; Sunday 18:00-00:00; Monday closed.","link":"https://www.stuttgart-tourist.de/en/a-reboots","location":"Bopserstraße 9, 70180 Stuttgart, Germany","lat":48.76720,"lng":9.17740,"vibe":"warm queer neighbourhood bar with karaoke, games and late-weekend ease","q":"The compact room gets busiest on programmed Friday and Saturday nights.","best":"Weekday for conversation; a listed karaoke or bingo night for the full community pulse.","crowd":"Queer locals, mixed friend groups, regulars and visitors.","dress":"Relaxed bar casual.","staff":"Official destination guide describes it as a home port for the queer community.","sources":["https://www.stuttgart-tourist.de/en/a-reboots"]},
  {"name":"VIVA Sauna","city":"stuttgart","type":"sauna","description":"Central gay sauna with Finnish sauna, steam bath, lounge and cruising areas. It is primarily a men-only adult space, while Monday and Tuesday are explicitly open to all genders; photography is prohibited throughout, and the official rules stress respectful conduct.","hours":"Daily 14:00-23:00; 18+ only. Monday and Tuesday welcome all genders; confirm theme days and entry price directly.","link":"https://vivasauna.de/","location":"Charlottenstraße 38, 70182 Stuttgart, Germany","lat":48.77710,"lng":9.18390,"vibe":"central adult sauna with a clear gay-community focus and practical weekday inclusion","q":"Theme days can change attendance; ordinary afternoons are generally calmer than evening peaks.","best":"Choose Monday or Tuesday for the all-genders format; otherwise verify the current theme day.","crowd":"Adult gay men on most days; all genders on Monday and Tuesday under the operator's published policy.","dress":"Sauna setting; follow house rules and consent expectations.","staff":"Official policy publishes age, gender-day, privacy and conduct rules.","sources":["https://vivasauna.de/","https://vivasauna.de/fragen-und-antworten/"]},
  {"name":"Club Lehmann","city":"stuttgart","type":"club","description":"A large techno institution whose regular Love*Pop date gives Stuttgart's gay community a reliable dance-floor night. It is not a permanent queer club: choose the named programme, not an arbitrary weekend, and expect the late, underground rhythm of a serious techno venue.","hours":"Friday 23:59-07:00; Saturday 23:59-09:00. Love*Pop and other queer programming are event-led; verify the current calendar.","link":"https://www.lehmannclub.de/","location":"Breitscheidstraße 12, 70174 Stuttgart, Germany","lat":48.77920,"lng":9.16780,"vibe":"dark techno room that becomes a queer dance destination on Love*Pop nights","q":"Door time, cover and capacity depend on the specific event.","best":"Attend a confirmed Love*Pop date and arrive with the programme rather than the generic club schedule.","crowd":"Techno regulars on standard nights; broad gay-community and allied dance crowd on Love*Pop.","dress":"Club-ready, comfortable for a late night; event guidance wins.","staff":"Stuttgart Tourism identifies Love*Pop as the gay community's regular date at the club.","sources":["https://www.stuttgart-tourist.de/en/a-club-lehmann","https://www.lehmannclub.de/"]}
]
$qa_places$) p(name text,city text,type text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,q text,best text,crowd text,dress text,staff text,sources jsonb)
), places as (
  select p.*,jsonb_build_object('entry_wait',q,'best_nights',best,'crowd_mix',crowd,'dress_code',dress,'staff_inclusivity',staff,'source_urls',sources,'research_status','current_official_or_municipal_source','updated_at','2026-10-27T00:00:00Z') intel from raw_places p
), upd as (
  update public.places t set type=p.type,description=p.description,hours=p.hours,link=p.link,location=p.location,lat=p.lat,lng=p.lng,vibe=p.vibe,vibe_tags=array[]::text[],venue_intel=p.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from places p where lower(trim(t.city))=p.city and lower(trim(t.name))=lower(trim(p.name)) returning t.id
)
insert into public.places(name,city,type,description,hours,link,location,lat,lng,vibe,vibe_tags,venue_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,type,description,hours,link,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from places p where not exists(select 1 from public.places t where lower(trim(t.city))=p.city and lower(trim(t.name))=lower(trim(p.name)));

with raw_events as (
  select * from jsonb_to_recordset($qa_events$
[
  {"name":"Stuttgart PRIDE Demonstration & Rally 2026","city":"stuttgart","description":"Stuttgart PRIDE's public demonstration moves through the city centre before the rally at Schlossplatz. It is the political centre of the city's Pride weekend, combining LGBTQIA+ demands, community visibility and large-scale public participation.","link":"https://www.stuttgart-pride.de/kundegebung/","date":"2026-07-25","start_date":"2026-07-25T12:00:00+02:00","end_date":"2026-07-25T20:00:00+02:00","location":"Stuttgart city centre and Schlossplatz, Stuttgart, Germany","lat":48.77845,"lng":9.17920,"vibe":"large civic Pride demonstration and public rally in the city centre","q":"Demonstration access and stage areas are crowded; use public transport and check the final route.","best":"Arrive before the march starts, then use the organiser's current route and rally information.","crowd":"LGBTQIA+ communities from Stuttgart and Baden-Württemberg, organisations, families, allies and visitors.","dress":"Pride expression with sun/rain layers and shoes suitable for a long city-centre day.","host":"IG CSD Stuttgart e.V., the city's dedicated Pride association.","sources":["https://www.stuttgart-pride.de/kundegebung/","https://www.stuttgart-pride.de/2026/05/27/csds-und-prides-in-baden-wuerttemberg-2026/"]},
  {"name":"CSD-Hocketse Stuttgart PRIDE 2026","city":"stuttgart","description":"Stuttgart's three-day Pride street festival combines the Kultur-Bühne at Marktplatz, an open-air disco at Schillerplatz and a community information mile in Kirchstraße. It pairs celebration with direct access to local organisations and services.","link":"https://www.stuttgart-pride.de/alle-infos-zur-hocketse/","date":"2026-07-24","start_date":"2026-07-24T16:00:00+02:00","end_date":"2026-07-26T20:00:00+02:00","location":"Marktplatz, Schillerplatz and Kirchstraße, Stuttgart, Germany","lat":48.77520,"lng":9.17730,"vibe":"three-day city-centre Pride festival with stages, open-air disco and community information","q":"The central squares and entry points become busy, especially around the Saturday demonstration.","best":"Use Friday for a calmer first orientation or arrive early for the community information mile.","crowd":"LGBTQIA+ locals, regional visitors, performers, community groups, families and allies.","dress":"Weather-ready Pride clothing and comfortable walking shoes.","host":"IG CSD Stuttgart e.V. with community organisations and volunteers.","sources":["https://www.stuttgart-pride.de/alle-infos-zur-hocketse/","https://www.stuttgart-pride.de/sponsoring/"]}
]
$qa_events$) e(name text,city text,description text,link text,date text,start_date timestamptz,end_date timestamptz,location text,lat double precision,lng double precision,vibe text,q text,best text,crowd text,dress text,host text,sources jsonb)
), events as (
  select e.*,jsonb_build_object('entry_wait',q,'best_arrival',best,'crowd_mix',crowd,'dress_code',dress,'host_inclusivity',host,'source_urls',sources,'research_status','official_organiser_schedule','updated_at','2026-10-27T00:00:00Z') intel from raw_events e
), upd as (
  update public.events t set description=e.description,link=e.link,date=e.date,start_date=e.start_date,end_date=e.end_date,location=e.location,lat=e.lat,lng=e.lng,vibe=e.vibe,vibe_tags=array[]::text[],event_intel=e.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from events e where lower(trim(t.city))=e.city and lower(trim(t.name))=lower(trim(e.name)) returning t.id
)
insert into public.events(name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,event_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,description,link,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from events e where not exists(select 1 from public.events t where lower(trim(t.city))=e.city and lower(trim(t.name))=lower(trim(e.name)));

with raw_services as (
  select * from jsonb_to_recordset($qa_services$
[
  {"name":"Weissenburg e.V. Counselling","city":"stuttgart","type":"other","provider":"Weissenburg e.V. – Zentrum LSBTIQA+ Stuttgart","contact":"Use the official counselling contact route","booking":"https://www.zentrum-weissenburg.de/","description":"Queer-aware counselling and navigation around coming out, discrimination, relationships, family, loneliness, gender identity and referrals, with specialised routes for queer men and for trans*, inter*, non-binary and agender people.","hours":"Appointment-led; café hours are separate. Contact before visiting and ask about video, telephone or step-free access.","link":"https://www.zentrum-weissenburg.de/","location":"Weißenburgstraße 28A, 70180 Stuttgart, Germany","lat":48.767623,"lng":9.178081,"vibe":"community-rooted queer counselling with local-network knowledge","lead":"Contact privately before attending and state any access, language or confidentiality need.","best":"A planned weekday contact rather than relying on café opening hours.","crowd":"LGBTQIA+ people, people questioning identity, relatives, friends and professionals.","prep":"Ask about the correct specialist counselling route, privacy, remote options and accessibility.","incl":"City-listed LGBTIQ+ counselling provider with targeted gender-identity and queer-men's services.","sources":["https://www.stuttgart.de/en/buergerinnen-und-buerger/chancengleichheit/lsbttiq/queere-beratungsangebote","https://www.zentrum-weissenburg.de/kontakt/"]},
  {"name":"AIDS-Hilfe Stuttgart","city":"stuttgart","type":"wellness","provider":"AIDS-Hilfe Stuttgart e.V.","contact":"0711 22 46 9-0","booking":"https://www.aidshilfe-stuttgart.de/index.php?article_id=1382","description":"Nonprofit provider of HIV/AIDS and sexual-health prevention, counselling and support. Individual anonymous rapid tests for HIV, syphilis and hepatitis C are offered by prior appointment, with qualified counselling before the test.","hours":"Office Monday-Friday 10:00-12:00 and Monday-Thursday 14:00-17:00. Rapid-test appointments: Thursday 14:00-17:00; book in advance.","link":"https://www.aidshilfe-stuttgart.de/","location":"Johannesstraße 19, 70176 Stuttgart, Germany","lat":48.77060,"lng":9.16280,"vibe":"confidential sexual-health counselling and anonymous rapid-test support","lead":"Call before attending; individual Thursday rapid tests require an appointment.","best":"Weekday contact before a test, with timing since possible exposure discussed confidentially.","crowd":"People living with HIV, LGBTQ+ people and all sexually active adults seeking confidential support.","prep":"Ask about appointment, anonymity, timing, language, cost/donation and result procedure.","incl":"Longstanding nonprofit working in prevention, counselling and support for people living with HIV.","sources":["https://www.aidshilfe-stuttgart.de/","https://www.aidshilfe-stuttgart.de/index.php?article_id=1382"]},
  {"name":"Trans* Stuttgart Coordination Office","city":"stuttgart","type":"other","provider":"Mission TRANS* e.V.","contact":"Use the official Mission TRANS* contact route","booking":"https://www.stuttgart.de/en/buergerinnen-und-buerger/chancengleichheit/lsbttiq/","description":"City-linked coordination and networking route for trans and non-binary people in Stuttgart, connecting community needs with counselling, self-help, public participation and events such as Trans* Pride Stuttgart.","hours":"Programme and event-led; verify current contact and meeting details before visiting.","link":"https://www.stuttgart.de/en/buergerinnen-und-buerger/chancengleichheit/lsbttiq/","location":"Stuttgart, Germany","lat":48.77580,"lng":9.18290,"vibe":"trans and non-binary visibility, coordination and community connection","lead":"Use the current official contact route for referral, programme or event information.","best":"Private advance contact for guidance suited to identity, urgency and access needs.","crowd":"Trans, non-binary and questioning people, community organisations and allies.","prep":"Ask about confidentiality, current programmes, referral options and accessibility.","incl":"Mission TRANS* operates Stuttgart's municipal coordination office for trans and non-binary concerns.","sources":["https://www.stuttgart.de/en/buergerinnen-und-buerger/chancengleichheit/lsbttiq/","https://www.stuttgart.de/en/buergerinnen-und-buerger/chancengleichheit/lsbttiq/queere-beratungsangebote"]}
]
$qa_services$) s(name text,city text,type text,provider text,contact text,booking text,description text,hours text,link text,location text,lat double precision,lng double precision,vibe text,lead text,best text,crowd text,prep text,incl text,sources jsonb)
), services as (
  select s.*,jsonb_build_object('booking_lead_time',lead,'best_time',best,'client_mix',crowd,'preparation',prep,'provider_inclusivity',incl,'source_urls',sources,'research_status','current_first_party_or_municipal_source','updated_at','2026-10-27T00:00:00Z') intel from raw_services s
), upd as (
  update public.services t set type=s.type,provider_name=s.provider,contact=s.contact,booking_link=s.booking,description=s.description,hours=s.hours,link=s.link,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],source='Official/provider sources; checked 2026-10-27',"lastChecked"=date '2026-10-27',verified=true,service_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from services s where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)) returning t.id
)
insert into public.services(name,city,type,provider_name,contact,booking_link,description,hours,link,location,lat,lng,vibe,vibe_tags,source,"lastChecked",verified,service_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,type,provider,contact,booking,description,hours,link,location,lat,lng,vibe,array[]::text[],'Official/provider sources; checked 2026-10-27',date '2026-10-27',true,intel,true,'approved',timezone('utc',now()) from services s where not exists(select 1 from public.services t where lower(trim(t.city))=s.city and lower(trim(t.name))=lower(trim(s.name)));

select public.qa_refresh_city_seo_status('stuttgart') where to_regprocedure('public.qa_refresh_city_seo_status(text)') is not null;

commit;

select c.slug,c.name,c.status,c.verified_place_count,c.seo_indexable,c.seo_requirements
from public.qa_cities c where c.slug = 'stuttgart';
